{
  "decisions": [
    {
      "entity_path": "config/archive_format",
      "change_type": "reject",
      "reasoning": "We rejected zstd because the downstream importer cannot decode it. The importer accepts zip and gzip. Use gzip for the smallest compatible export until the importer gains zstd support.",
      "constraint": "Nightly archives must be decodable by the downstream importer.",
      "stale_when": "Downstream importer adds tested zstd support."
    }
  ],
  "note": "This file is independent of any connected memory server."
}

{
  "status": "applied",
  "key": "archive_format",
  "value": "gzip",
  "rationale": "Among the three supported formats (zip 12 MB, gzip 9 MB, zstd 6 MB), zstd remains rejected because the downstream importer still cannot decode it — the project evidence confirms the importer has not been upgraded. Of the two compatible formats, gzip produces the smallest output (9 MB vs. zip's 12 MB). The maintained decision record explicitly directs using gzip as the smallest compatible choice until the importer gains zstd support."
}
